design.prefetcher_source:
#include <cstdint>
#include "address.h"
#include "modules.h"
#include <vector>
#include <algorithm>
#include <cstddef>

struct gen_fill_only_conservative_s1 : public champsim::modules::prefetcher {
  using prefetcher::prefetcher;

  uint32_t prefetcher_cache_operate(champsim::address addr, champsim::address ip,
                                     uint8_t cache_hit, bool useful_prefetch,
                                     access_type type, uint32_t metadata_in) {
    // As per the design brief, this prefetcher never trains on demand misses
    // and issues prefetches only from cache-fill feedback.
    // Therefore, no prefetching logic is implemented here.
    return metadata_in;
  }

  uint32_t prefetcher_cache_fill(champsim::address addr, long set, long way,
                                  uint8_t prefetch, champsim::address evicted_addr,
                                  uint32_t metadata_in) {
    // This is the trigger for prefetching, as per the design brief.
    // It issues prefetches at most one line ahead of the filled address.

    // Convert the physical address to a block number for arithmetic.
    champsim::block_number current_block{addr};

    // Calculate the address for the next block (one line ahead).
    champsim::block_number prefetch_block = current_block + 1;

    // Issue the prefetch request for the calculated block.
    // The 'fill_this_level' parameter is set to true to indicate that
    // this prefetch should fill into the current cache level.
    prefetch_line(champsim::address{prefetch_block}, true, metadata_in);

    return metadata_in;
  }
};

